PlannerSearchBar.t-props:
{
                        search:         state.productSearch,
                        activeFilter:   state.activeFilter,
                        activeGroupBy:  state.groupBy,
                        filterDefs: [
                            { key: 'with_mos', label: 'Con OFs planificadas' },
                            { key: 'no_mos',   label: 'Sin OFs planificadas' },
                            { key: 'gap',      label: 'Con brecha (OFs menor que forecast)' }
                        ],
                        groupByDefs: [
                            { key: 'sale_category',  label: 'Categoría de venta' },
                            { key: 'product_categ',  label: 'Familia de producto' }
                        ],
                        onSearch:        (t) => this.setSearch(t),
                        onFilterChange:  (k) => this.setFilter(k),
                        onGroupByChange: (k) => this.setGroupBy(k)
                    }
